class Card {
    final String label;
    final int copies;
    private Card(Builder b) { label = b.label; copies = b.copies; }
    static class Builder {
        String label; int copies;
        Builder label(String value) { label = value; return this; }
        Builder copies(int value) { copies = value; return this; }
        Card build() {
            if (label == null || label.isBlank() || copies <= 0)
                throw new IllegalStateException("Заполните карточку");
            return new Card(this);
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Card card = new Card.Builder().label("Отчёт").copies(2).build();
        System.out.println(card.label + ":" + card.copies);
    }
}

